fd_set read_fds, write_fds;
struct timeval tv;
int max_fd = 5; // Highest descriptor number

FD_ZERO(&read_fds);
FD_ZERO(&write_fds);
FD_SET(0, &read_fds); // Monitor stdin

tv.tv_sec = 1;
tv.tv_usec = 500000; // 1.5 second timeout

// Call select(): nfds, read, write, except, timeout
int ready = select(max_fd + 1, &read_fds, &write_fds, NULL, &tv);

if (ready > 0) {
    if (FD_ISSET(0, &read_fds)) {
        // Stdin is ready to read
    }
}
// else timeout or error (-1)
